	@Test
	void retainsManifestWhenMarkerRemovalFails() throws IOException {
		Path target = temporaryDirectory.resolve("cleanup-failure");
		Path marker = target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME);
		try (LmdbBulkLoadGeneration generation = LmdbBulkLoadGeneration.create(target, (index, source, destination) -> {
			// Existing hook injects a real deletion failure without changing production or relying on permissions.
			Files.delete(marker);
			Files.createDirectory(marker);
			Files.writeString(marker.resolve("prevents-deletion"), "test-owned fault");
		})) {
			Files.write(generation.directory().resolve("artifact.bin"), ARTIFACT);
			assertThrows(DirectoryNotEmptyException.class, () -> generation.publish(STATISTICS));
			assertTrue(Files.isRegularFile(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)),
					"Failed marker removal must retain the artifact ownership/checksum manifest");
			assertArrayEquals(ARTIFACT, Files.readAllBytes(target.resolve("artifact.bin")));
		}
	}

	@Test
	void recoversFullyPromotedMarkerlessManifest() throws IOException {
		PreparedPublication prepared = preparePublication("markerless");
		Files.move(prepared.directory().resolve("artifact.bin"), prepared.target().resolve("artifact.bin"));
		Files.delete(prepared.directory());
		Files.delete(prepared.target().resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME));

		try (LmdbBulkLoadGeneration recovered = LmdbBulkLoadGeneration.create(prepared.target())) {
			assertTrue(recovered.recoveredPublication());
			assertEquals(STATISTICS, recovered.recoveredStatistics());
			recovered.finishRecoveredPublication();
			recovered.finishRecoveredPublication();
		}
		assertArrayEquals(ARTIFACT, Files.readAllBytes(prepared.target().resolve("artifact.bin")));
		assertFalse(Files.exists(prepared.target().resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)));
		assertFalse(Files.exists(prepared.target().resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)));
	}

	@Test
	void refusesManifestlessPromotedArtifactsWithoutDeletingThem() throws IOException {
		Path target = temporaryDirectory.resolve("legacy-manifestless");
		byte[][] savedMarker = new byte[1][];
		try (LmdbBulkLoadGeneration generation = LmdbBulkLoadGeneration.create(target,
				(index, source, destination) -> savedMarker[0] = Files.readAllBytes(
						target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)))) {
			Files.write(generation.directory().resolve("artifact.bin"), ARTIFACT);
			generation.publish(STATISTICS);
		}
		Files.write(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME), savedMarker[0]);

		IOException failure = assertThrows(IOException.class, () -> LmdbBulkLoadGeneration.create(target));
		assertTrue(failure.getMessage().contains("unexpected entries"));
		assertArrayEquals(ARTIFACT, Files.readAllBytes(target.resolve("artifact.bin")));
		assertArrayEquals(savedMarker[0], Files.readAllBytes(target.resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME)));
		assertFalse(Files.exists(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)));
	}

	@ParameterizedTest
	@EnumSource(value = PublicationStage.class, names = { "MANIFEST_DURABLE", "ARTIFACT_MOVED", "GENERATION_REMOVED",
			"BEFORE_ARTIFACTS_FORCE", "ARTIFACTS_DURABLE", "BEFORE_PUBLICATION_DIRECTORY_FORCE",
			"PUBLICATION_DIRECTORY_DURABLE", "BEFORE_MARKER_DELETE", "MARKER_REMOVED", "BEFORE_MARKER_DIRECTORY_FORCE",
			"MARKER_REMOVAL_DURABLE", "BEFORE_MANIFEST_DELETE" })
	void recoversAfterEachPublicationFailureWithoutLosingOwnership(PublicationStage cut) throws IOException {
		Path target = temporaryDirectory.resolve("cut-" + cut);
		try (LmdbBulkLoadGeneration generation = LmdbBulkLoadGeneration.create(target, failingAt(cut))) {
			Files.write(generation.directory().resolve("artifact.bin"), ARTIFACT);
			Path nested = Files.createDirectories(generation.directory().resolve("directory/nested"));
			Files.write(nested.resolve("contents.bin"), ARTIFACT);
			Files.createDirectory(generation.directory().resolve("empty-directory"));
			assertThrows(IOException.class, () -> generation.publish(STATISTICS));
		}
		assertTrue(Files.isRegularFile(target.resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)));
		try (LmdbBulkLoadGeneration recovered = LmdbBulkLoadGeneration.create(target)) {
			assertTrue(recovered.recoveredPublication());
			assertEquals(STATISTICS, recovered.recoveredStatistics());
			recovered.finishRecoveredPublication();
			recovered.finishRecoveredPublication();
		}
		assertArrayEquals(ARTIFACT, Files.readAllBytes(target.resolve("artifact.bin")));
		assertArrayEquals(ARTIFACT, Files.readAllBytes(target.resolve("directory/nested/contents.bin")));
		assertTrue(Files.isDirectory(target.resolve("empty-directory")));
	}

