	@Test
	void refusesMismatchedOrForeignMarkerlessOutputWithoutDeletingAnything() throws IOException {
		for (boolean foreign : List.of(false, true)) {
			PreparedPublication prepared = preparePublication("orphan-mismatch-" + foreign);
			Files.move(prepared.directory().resolve("artifact.bin"), prepared.target().resolve("artifact.bin"));
			Files.delete(prepared.directory());
			Files.delete(prepared.target().resolve(LmdbBulkLoadGeneration.MARKER_FILE_NAME));
			Path preserved = prepared.target().resolve(foreign ? "owner-notes.txt" : "artifact.bin");
			Files.writeString(preserved, "must survive");
			byte[] manifest = Files.readAllBytes(prepared.target().resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME));
			assertThrows(IOException.class, () -> LmdbBulkLoadGeneration.create(prepared.target()));
			assertEquals("must survive", Files.readString(preserved));
			assertArrayEquals(manifest,
					Files.readAllBytes(prepared.target().resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME)));
		}
	}

	@Test
	void refusesUnsafeManifestPathsAndReservedNamesBeforeMutation() throws IOException {
		for (String name : List.of("../outside", ".", "..", LmdbBulkLoadGeneration.MARKER_FILE_NAME,
				LmdbBulkLoadGeneration.MANIFEST_FILE_NAME, LmdbBulkLoadGeneration.LOCK_FILE_NAME,
				".lmdb-bulk-generation-foreign")) {
			PreparedPublication prepared = preparePublication("unsafe-" + Math.abs(name.hashCode()));
			Path manifest = prepared.target().resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME);
			Properties properties = new Properties();
			try (var input = Files.newInputStream(manifest)) {
				properties.load(input);
			}
			properties.setProperty("artifact.0", name);
			try (var output = Files.newOutputStream(manifest)) {
				properties.store(output, "test-owned invalid descriptor");
			}
			assertThrows(IOException.class, () -> LmdbBulkLoadGeneration.create(prepared.target()), name);
			assertArrayEquals(ARTIFACT, Files.readAllBytes(prepared.directory().resolve("artifact.bin")));
			assertTrue(Files.exists(manifest));
		}
	}

	@Test
	void refusesMetadataAndArtifactSymbolicLinksWithoutFollowingThem() throws IOException {
		for (String entry : List.of(LmdbBulkLoadGeneration.MARKER_FILE_NAME,
				LmdbBulkLoadGeneration.MANIFEST_FILE_NAME, "artifact.bin")) {
			PreparedPublication prepared = preparePublication("symlink-" + entry);
			Path file = entry.equals("artifact.bin") ? prepared.directory().resolve(entry)
					: prepared.target().resolve(entry);
			Path external = temporaryDirectory.resolve("external-" + entry);
			Files.move(file, external);
			Files.createSymbolicLink(file, external);
			byte[] expected = Files.readAllBytes(external);
			assertThrows(IOException.class, () -> LmdbBulkLoadGeneration.create(prepared.target()));
			assertTrue(Files.isSymbolicLink(file));
			assertArrayEquals(expected, Files.readAllBytes(external));
		}
	}

	@Test
	void refusesInvalidManifestVersionsDescriptorsAndStatisticsBeforeMutation() throws IOException {
		List<String[]> invalidProperties = List.of(new String[] { "version", "999" },
				new String[] { "generation", ".lmdb-bulk-generation-wrong" }, new String[] { "artifact.count", "-1" },
				new String[] { "artifact.count", "2147483647" }, new String[] { "artifact.0.type", "symlink" },
				new String[] { "artifact.0.size", "-1" }, new String[] { "artifact.0.sha256", "not-a-sha256" },
				new String[] { "result.stored-statements", "-1" });
		for (int index = 0; index < invalidProperties.size(); index++) {
			PreparedPublication prepared = preparePublication("invalid-metadata-" + index);
			Path manifest = prepared.target().resolve(LmdbBulkLoadGeneration.MANIFEST_FILE_NAME);
			Properties properties = new Properties();
			try (var input = Files.newInputStream(manifest)) {
				properties.load(input);
			}
			String[] invalid = invalidProperties.get(index);
			properties.setProperty(invalid[0], invalid[1]);
			try (var output = Files.newOutputStream(manifest)) {
				properties.store(output, "test-owned malformed metadata");
			}
			byte[] preservedManifest = Files.readAllBytes(manifest);
			assertThrows(IOException.class, () -> LmdbBulkLoadGeneration.create(prepared.target()), invalid[0]);
			assertArrayEquals(preservedManifest, Files.readAllBytes(manifest));
			assertArrayEquals(ARTIFACT, Files.readAllBytes(prepared.directory().resolve("artifact.bin")));
		}
	}

	private static LmdbBulkLoadGeneration.PromotionHook failingAt(PublicationStage cut) {
		return new LmdbBulkLoadGeneration.PromotionHook() {
			@Override
			public void beforeMove(int index, Path source, Path target) {
			}

			@Override
			public void onStage(PublicationStage stage) throws IOException {
				if (stage == cut) {
					throw new IOException("test publication failure at " + stage);
				}
			}
		};
	}

	private PreparedPublication preparePublication(String name) throws IOException {
		Path target = temporaryDirectory.resolve(name);
		Path directory;
		try (LmdbBulkLoadGeneration generation = LmdbBulkLoadGeneration.create(target, (index, source, destination) -> {
			throw new IOException("test publication cut before first promotion");
		})) {
			directory = generation.directory();
			Files.write(directory.resolve("artifact.bin"), ARTIFACT);
			IOException failure = assertThrows(IOException.class, () -> generation.publish(STATISTICS));
			assertEquals("test publication cut before first promotion", failure.getMessage());
		}
		return new PreparedPublication(target, directory);
	}

	private record PreparedPublication(Path target, Path directory) {
	}
